import frappe from frappe import _
def execute(filters=None): columns = get_columns() data = get_data(filters) return columns, data
def get_columns(): return [ {"label": _("ID"), "fieldname": "name", "fieldtype": "Link", "options": "{{doctype}}", "width": 150}, {"label": _("Date"), "fieldname": "date", "fieldtype": "Date", "width": 100}, {"label": _("Amount"), "fieldname": "amount", "fieldtype": "Currency", "width": 120}, ]
def get_data(filters): conditions = get_conditions(filters)
return frappe.db.sql(""" SELECT name, date, amount FROM `tab{{doctype}}` WHERE docstatus = 1 {conditions} ORDER BY date DESC """.format(conditions=conditions), filters, as_dict=1)
def get_conditions(filters): conditions = []
if filters.get("from_date"): conditions.append("date >= %(from_date)s") if filters.get("to_date"): conditions.append("date <= %(to_date)s")
return " AND " + " AND ".join(conditions) if conditions else ""
